<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/bootstrap.php';
require_admin();
$rows=[];
try{$rows=$pdo->query("SELECT t.id,t.name,COUNT(DISTINCT tt.id) classes_per_period,COUNT(DISTINCT se.student_id) students_taught,COALESCE(SUM(TIME_TO_SEC(TIMEDIFF(tt.end_time,tt.start_time))/3600),0) teaching_hours,COALESCE(rs.total_commission,0) estimated_commission,COALESCE(rs.total_paid,0) actual_payment,COALESCE(rs.total_commission,0)-COALESCE(rs.total_paid,0) outstanding_payment FROM teachers t LEFT JOIN timetable tt ON tt.teacher_id=t.id AND tt.deleted_at IS NULL AND tt.date>=DATE_SUB(CURDATE(),INTERVAL 7 DAY) LEFT JOIN student_enrollments se ON se.class_id=tt.class_id LEFT JOIN revenue_summary rs ON rs.teacher_id=t.id WHERE t.deleted_at IS NULL GROUP BY t.id,t.name,rs.total_commission,rs.total_paid ORDER BY t.name")->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){}
include __DIR__ . '/../includes/header.php';?>
<div class="container-fluid py-4"><h1 class="h3"><i class="bi bi-person-workspace"></i> Teacher workload analytics</h1><p class="text-muted">Last seven days, using the existing timetable and commission summaries.</p><div class="card shadow-sm border-0"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Teacher</th><th>Classes/week</th><th>Students</th><th>Hours</th><th>Estimated commission</th><th>Actual payment</th><th>Outstanding</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?= (int)$r['classes_per_period']?></td><td><?= (int)$r['students_taught']?></td><td><?=number_format((float)$r['teaching_hours'],1)?></td><td>Rs <?=number_format((float)$r['estimated_commission'],2)?></td><td>Rs <?=number_format((float)$r['actual_payment'],2)?></td><td class="text-warning">Rs <?=number_format((float)$r['outstanding_payment'],2)?></td></tr><?php endforeach;?></tbody></table></div></div></div><?php include __DIR__ . '/../includes/footer.php';?>
